                '周期毫秒':0,'会话上限':(random.choice([0,1,2])),
                '排队优先级':(100 if tid=="g" else random.randint(0,90)),'超限':'拒绝'})
        for u in USERS:
            if random.random() < 0.6:
                binds.append([u, random.choice(["g","s"])])
    d = {'版本':8,'会话':{'总数':total,'每用户':s._per,'空闲毫秒':100000,'租期毫秒':100000},
      '地址池':[{'标识':'default','CIDR':'10.0.0.0/28','保留':[],'静态':[]}],
      '模板':templates,'用户模板':binds,
      '容量':{'队列上限':1024,'最大等待毫秒':0},'认证':{'最大失败':5,'锁定毫秒':1000}}
    s.load_config(json.dumps(d, ensure_ascii=False))
    return s, total

mismatches = 0
for trial in range(400):
    s, total = build()
    k = 0
    t0 = random.randint(0, 50)
    n_init = random.randint(0, total + 2)
    for i in range(n_init):
        k += 1
        s.capacity(f"k{k}", "申请", f"e{i}", (random.choice(USERS), 'pw', random.choice([500,2000,5000])), t0)
    nq = random.randint(0, 6)
    for j in range(nq):
        k += 1
        at = random.randint(t0, t0+30)
        s.capacity(f"k{k}", "申请", f"q{j}", (random.choice(USERS), 'pw', random.choice([100,1000,4000])), at)
    now = random.randint(t0, t0 + 4000)
    lim = random.randint(1,10)
    fc = json.loads(s.capacity_forecast(now, limit=lim))
    pred = {it["会话"]: it["结果"] for it in fc["项目"]}
    s.capacity(f"adv{trial}", "推进", "", None, now)
    ev = json.loads(s.capacity_events(0, 1000))["事件"]
    actual = {}
    for e in ev:
        if e["时刻"] == now and e["结果"] in ("超时", "晋升"):
            actual[e["会话"]] = e["结果"]
    bad = []
