        act = actual.get(sid)
        if res in ("超时", "晋升"):
            ok = act == res
        else:
            ok = act is None
        if not ok: bad.append((sid, res, act))
    if bad:
        mismatches += 1
        if mismatches <= 5:
            print("MISMATCH trial", trial, bad, [ (it['会话'],it['结果'],it['原因']) for it in fc['项目']])
print("mismatches:", mismatches, "/400")
